package com.arena.core.training;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import java.util.*;
@io.swagger.v3.oas.annotations.tags.Tag(name="Academy setup")
@RestController @RequestMapping("/api/academy") @RequiredArgsConstructor
public class AcademySetupController {
 private final AcademySetupService setup;
 private final AcademyFacilityService facilities;
 private final AcademyAuthorization authorization;
 @io.swagger.v3.oas.annotations.Operation(summary="Get academy setup completion", description="Active academy membership. Progress is Owner/Manager; profile/confirmation are Owner-only. Membership identity comes from the authenticated account. Legacy play-area APIs retain existing restrictions.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode="200",description="Successful operation",content=@io.swagger.v3.oas.annotations.media.Content(mediaType="application/json",schema=@io.swagger.v3.oas.annotations.media.Schema(implementation=com.arena.core.documentation.ResponseDocumentation.SetupProgress.class)))
 @GetMapping("/setup") public Map<String,Object> progress(@AuthenticationPrincipal Jwt jwt){return setup.progress(jwt);}
 @io.swagger.v3.oas.annotations.Operation(summary="Update academy setup profile", description="Active academy membership. Progress is Owner/Manager; profile/confirmation are Owner-only. Membership identity comes from the authenticated account. Legacy play-area APIs retain existing restrictions.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode="200",description="Successful operation",content=@io.swagger.v3.oas.annotations.media.Content(mediaType="application/json",schema=@io.swagger.v3.oas.annotations.media.Schema(implementation=com.arena.core.documentation.ResponseDocumentation.SetupProgress.class)))
 @PutMapping("/setup/profile") public Map<String,Object> profile(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody AcademySetupService.Profile r){return setup.profile(jwt,r);}
 @io.swagger.v3.oas.annotations.Operation(summary="Confirm staffing choice or setup review", description="Active academy membership. Progress is Owner/Manager; profile/confirmation are Owner-only. Membership identity comes from the authenticated account. Legacy play-area APIs retain existing restrictions.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode="200",description="Successful operation",content=@io.swagger.v3.oas.annotations.media.Content(mediaType="application/json",schema=@io.swagger.v3.oas.annotations.media.Schema(implementation=com.arena.core.documentation.ResponseDocumentation.SetupProgress.class)))
 @PutMapping("/setup/confirmation") public Map<String,Object> confirm(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody AcademySetupService.Confirmation r){return setup.confirm(jwt,r);}
 @io.swagger.v3.oas.annotations.Operation(summary="Get authenticated academy membership", description="Active academy membership. Progress is Owner/Manager; profile/confirmation are Owner-only. Membership identity comes from the authenticated account. Legacy play-area APIs retain existing restrictions.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode="200",description="Successful operation",content=@io.swagger.v3.oas.annotations.media.Content(mediaType="application/json",schema=@io.swagger.v3.oas.annotations.media.Schema(implementation=com.arena.core.documentation.ResponseDocumentation.Membership.class)))
 @GetMapping("/membership") public Map<String,Object> membership(@AuthenticationPrincipal Jwt jwt){var a=authorization.actor(jwt);return Map.of("roles",a.roles(),"academyId",a.academyId(),"staffId",a.membership()==null?0:a.membership().getId());}
 @io.swagger.v3.oas.annotations.Operation(summary="List legacy academy play areas", description="Active academy membership. Progress is Owner/Manager; profile/confirmation are Owner-only. Membership identity comes from the authenticated account. Legacy play-area APIs retain existing restrictions.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @GetMapping("/facilities") public List<AcademyPlayArea> areas(@AuthenticationPrincipal Jwt jwt){return facilities.list(jwt);}
 @io.swagger.v3.oas.annotations.Operation(summary="Create a legacy play area", description="Active academy membership. Progress is Owner/Manager; profile/confirmation are Owner-only. Membership identity comes from the authenticated account. Legacy play-area APIs retain existing restrictions. Legacy play-area creation. Supported managed Snooker/Badminton resources must use the versioned facility generation API; immutable generated codes may not be bypassed through this legacy route.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @PostMapping("/facilities") public AcademyPlayArea create(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody AcademyFacilityService.Area r){return facilities.save(jwt,null,r);}
 @io.swagger.v3.oas.annotations.Operation(summary="Update a legacy play area", description="Active academy membership. Progress is Owner/Manager; profile/confirmation are Owner-only. Membership identity comes from the authenticated account. Legacy play-area APIs retain existing restrictions. Legacy play-area update, tenant-scoped and versioned. Managed resources retain immutable sport/code; use versioned facility PATCH for managed pricing.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @PutMapping("/facilities/{id}") public AcademyPlayArea update(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody AcademyFacilityService.Area r){return facilities.save(jwt,id,r);}
}
